def count_valid_distributions(n):
    MOD = 10**9 + 7

    # dp[i][j] will store the number of ways to distribute coins for the first i gnomes
    # with j being the number of invalid triplets (0, 1, 2, 3)
    dp = [[0] * 4 for _ in range(3 * n + 1)]

    # Base case: 0 gnomes, 0 invalid triplets
    dp[0][0] = 1

    for i in range(1, 3 * n + 1):
        for j in range(4):
            # Consider adding 1, 2, or 3 coins to the i-th gnome
            for coins in range(1, 4):
                if i >= coins:
                    # Calculate the new number of invalid triplets
                    new_j = j
                    if coins == 1:
                        if i % 3 == 1:
                            new_j += 1
                        elif i % 3 == 2:
                            new_j += 2
                    elif coins == 2:
                        if i % 3 == 1:
                            new_j += 2
                        elif i % 3 == 2:
                            new_j += 1
                    elif coins == 3:
                        new_j += 3

                    # Ensure new_j is within bounds
                    new_j = min(new_j, 3)

                    # Update dp table
                    dp[i][new_j] = (dp[i][new_j] + dp[i - coins][j]) % MOD

    # Sum up all ways with 0 invalid triplets
    return dp[3 * n][0]

# Read input
n = int(input())

# Calculate and print the result
result = count_valid_distributions(n)
print(result)
